import{_ as a,o as t,c as s,a5 as r}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-09","description":"","frontmatter":{"title":"AI 动态 · 2026-08-09","date":"2026-08-09T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-09.md","filePath":"news/2026-08/ai-news-2026-08-09.md","lastUpdated":null}'),n={name:"news/2026-08/ai-news-2026-08-09.md"};function o(i,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-09" tabindex="-1">AI 动态 · 2026-08-09 <a class="header-anchor" href="#ai-动态-·-2026-08-09" aria-label="Permalink to &quot;AI 动态 · 2026-08-09&quot;">​</a></h1><blockquote><p>截至 2026-08-09。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="openai-收购演示文稿初创公司-nextslide" tabindex="-1">OpenAI 收购演示文稿初创公司 NextSlide <a class="header-anchor" href="#openai-收购演示文稿初创公司-nextslide" aria-label="Permalink to &quot;OpenAI 收购演示文稿初创公司 NextSlide&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-09">2026-08-09</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/187b262fbc99.jpg" alt="配图"></p><p>OpenAI 宣布收购 AI 演示文稿初创公司 NextSlide，其团队成员现已加入 ChatGPT 团队。NextSlide 的产品可将提示、笔记或文档转化为精美的可编辑演示文稿。创始人 Ahmed Beshry 表示，收购发生在今年早些时候，财务条款未披露。此次收购旨在增强 ChatGPT 的演示文稿生成能力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/08/openai-acquires-presentation-startup-nextslide/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="opus-5-烧-6-9-亿-token-做游戏-gpt-5-6-用-5-美元复刻" tabindex="-1">Opus 5 烧 6.9 亿 token 做游戏，GPT-5.6 用 5 美元复刻 <a class="header-anchor" href="#opus-5-烧-6-9-亿-token-做游戏-gpt-5-6-用-5-美元复刻" aria-label="Permalink to &quot;Opus 5 烧 6.9 亿 token 做游戏，GPT-5.6 用 5 美元复刻&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-09">2026-08-09</time></p><p>网友用 Opus 5 单提示词生成了一款精美的水上快艇竞速游戏《INK TIDE》，耗资 423 美元、6.9 亿 token。随后另一位网友在 Codex 中用 GPT-5.6 Sol 复刻了该游戏，仅花费 5 美元，展示了 GPT-5.6 在代码生成和成本效率上的优势。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/468766.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="claude-code-将默认使用自动模式-尽管测试失败率达-11" tabindex="-1">Claude Code 将默认使用自动模式，尽管测试失败率达 11% <a class="header-anchor" href="#claude-code-将默认使用自动模式-尽管测试失败率达-11" aria-label="Permalink to &quot;Claude Code 将默认使用自动模式，尽管测试失败率达 11%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">techi.com</span><time datetime="2026-08-09">2026-08-09</time></p><p>Anthropic 的 Claude Code 工具将默认启用自动模式，尽管在内部测试中失败率高达 11%。这一决定引发了对 AI 编码工具可靠性的担忧，但 Anthropic 可能认为自动模式带来的效率提升值得承担风险。开发者需谨慎使用。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMifkFVX3lxTE5qZlNsODNGODJPY2ptUzZObWVWdjh2cHRBNXN1QUd4anAyZWVYQm5sMkhMQzNkQjg5UHJFdGpwVUpMVVlWN2haUVg0SnZzQlBpVm43Wjl2LXZFN2xQdC1qWnJuOEZrUmlPNGg0eTN1RmlVMWdhdml1eUdxNHV4Zw?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="code-graph-rag-面向多语言代码库的终极-rag-工具" tabindex="-1">code-graph-rag：面向多语言代码库的终极 RAG 工具 <a class="header-anchor" href="#code-graph-rag-面向多语言代码库的终极-rag-工具" aria-label="Permalink to &quot;code-graph-rag：面向多语言代码库的终极 RAG 工具&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">vitali87/code-graph-rag</span><time datetime="2026-08-09">2026-08-09</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/be68f930e241.png" alt="配图"></p><p>开源项目 code-graph-rag 旨在为大型 monorepo 提供终极 RAG 解决方案，结合 AI 和知识图谱，支持查询、理解和编辑多语言代码库。该项目可帮助开发者高效地导航和操作复杂代码库，提升开发效率。</p><p class="news-entry-source"><a href="https://github.com/vitali87/code-graph-rag" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="daily-stock-analysis-llm-驱动的多市场股票分析系统" tabindex="-1">daily_stock_analysis：LLM 驱动的多市场股票分析系统 <a class="header-anchor" href="#daily-stock-analysis-llm-驱动的多市场股票分析系统" aria-label="Permalink to &quot;daily_stock_analysis：LLM 驱动的多市场股票分析系统&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">ZhuLinsen/daily_stock_analysis</span><time datetime="2026-08-09">2026-08-09</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/b9ffcce1a387.png" alt="配图"></p><p>开源项目 daily_stock_analysis 是一个 LLM 驱动的多市场股票智能分析系统，支持多源行情、实时新闻、决策看板与自动推送，并支持零成本定时运行。该项目适合个人投资者或开发者快速搭建股票分析工具。</p><p class="news-entry-source"><a href="https://github.com/ZhuLinsen/daily_stock_analysis" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="企业-ai-初创公司-happyrobot-融资-1-5-亿美元-跻身独角兽" tabindex="-1">企业 AI 初创公司 HappyRobot 融资 1.5 亿美元，跻身独角兽 <a class="header-anchor" href="#企业-ai-初创公司-happyrobot-融资-1-5-亿美元-跻身独角兽" aria-label="Permalink to &quot;企业 AI 初创公司 HappyRobot 融资 1.5 亿美元，跻身独角兽&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wowtale</span><time datetime="2026-08-08">2026-08-08</time></p><p>企业 AI 初创公司 HappyRobot 宣布获得 1.5 亿美元融资，估值达到独角兽级别。该公司专注于开发能够真正执行工作的 AI 代理，帮助企业自动化业务流程。此次融资表明投资者对企业级 AI 代理市场的信心。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMiU0FVX3lxTE9wRlZzUlR5U2Q2bFBiTURiSTF0eGtHSHFDcFlrT1Zmd3BqNExXVy1SVEphVXZ5ZVV0amZIeUVqZ0hXWVc0SEZyUlh3eXQxeUQ3RjJv?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ai-编程工具-cursor-估值达-34-亿美元" tabindex="-1">AI 编程工具 Cursor 估值达 34 亿美元 <a class="header-anchor" href="#ai-编程工具-cursor-估值达-34-亿美元" aria-label="Permalink to &quot;AI 编程工具 Cursor 估值达 34 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">tech-insider.org</span><time datetime="2026-08-09">2026-08-09</time></p><p>AI 编程工具 Cursor 在 AI 编码初创公司洗牌中脱颖而出，估值达到 34 亿美元。Cursor 凭借其强大的代码生成和编辑能力，成为开发者喜爱的工具之一，此次估值反映了市场对 AI 编程工具的高度认可。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMibkFVX3lxTE0zWGtWOXlJd0h6UTA4SkNEeUxBRUd4RHYxWk8teEhVQmRiTVRQaEdfcFdqQk9vSDNDYkE4cFktTUdnNkxlVS1uMFJDR0VYanhqSFRSX3VxaTBreVpFVFNNOWZ0T0Rsd0QzU3RmWUdR?oc=5" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="net-maui-正式迈向-handler-架构时代" tabindex="-1">.NET MAUI 正式迈向 Handler 架构时代 <a class="header-anchor" href="#net-maui-正式迈向-handler-架构时代" aria-label="Permalink to &quot;.NET MAUI 正式迈向 Handler 架构时代&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-08">2026-08-08</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/523fc86668c5.jpg" alt="配图"></p><p>.NET 11 Preview 6 对 .NET MAUI 进行重大架构更新，将 CollectionView 实现带至 Windows 平台，并推动 Android Shell 迁移到 handler 模型。同时移除 Xamarin.Forms 兼容包，提升 Native AOT 兼容性。开发者需注意自定义 Shell 行为的兼容性测试。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/sbMEk7BQoWXRcl5ZFvkD?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
